// ==========================================
// DIRECT TOUCH & MOUSE DRAG (PHOTO OR LOGO)
// ==========================================
let isDraggingPhoto = false;
let isDraggingLogo = false;
let dragStartX = 0;
let dragStartY = 0;
let initialImgPosX = 0;
let initialImgPosY = 0;
let initialLogoPosX = 0;
let initialLogoPosY = 0;

function getCanvasCoords(clientX, clientY) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  return {
    x: (clientX - rect.left) * scaleX,
    y: (clientY - rect.top) * scaleY
  };
}

function isInsideLogo(cx, cy) {
  const padding = 25;
  return (
    cx >= lastLogoBox.x - padding &&
    cx <= lastLogoBox.x + lastLogoBox.w + padding &&
    cy >= lastLogoBox.y - padding &&
    cy <= lastLogoBox.y + lastLogoBox.h + padding
  );
}

function startDrag(clientX, clientY) {
  const pos = getCanvasCoords(clientX, clientY);
  if (isInsideLogo(pos.x, pos.y)) {
    isDraggingLogo = true;
    isDraggingPhoto = false;
    dragStartX = pos.x;
    dragStartY = pos.y;
    initialLogoPosX = logoPosX;
    initialLogoPosY = logoPosY;
    canvas.style.cursor = 'move';
  } else if (userImage) {
    isDraggingPhoto = true;
    isDraggingLogo = false;
    canvas.classList.add('is-dragging');
    dragStartX = pos.x;
    dragStartY = pos.y;
    initialImgPosX = imgPosX;
    initialImgPosY = imgPosY;
    canvas.style.cursor = 'grabbing';
  }
}

function moveDrag(clientX, clientY) {
  if (!isDraggingPhoto && !isDraggingLogo) {
    const pos = getCanvasCoords(clientX, clientY);
    if (isInsideLogo(pos.x, pos.y)) {
      canvas.style.cursor = 'move';
    } else if (userImage) {
      canvas.style.cursor = 'grab';
    } else {
      canvas.style.cursor = 'default';
    }
    return;
  }

  const pos = getCanvasCoords(clientX, clientY);
  const dx = pos.x - dragStartX;
  const dy = pos.y - dragStartY;

  if (isDraggingLogo) {
    logoPosX = Math.round(initialLogoPosX + dx);
    logoPosY = Math.round(initialLogoPosY + dy);
    if (logoPosXRange) logoPosXRange.value = logoPosX;
    if (logoPosYRange) logoPosYRange.value = logoPosY;
    renderCard();
  } else if (isDraggingPhoto) {
    imgPosX = Math.round(initialImgPosX + dx);
    imgPosY = Math.round(initialImgPosY + dy);
    if (posXRange) posXRange.value = imgPosX;
    if (posYRange) posYRange.value = imgPosY;
    renderCard();
  }
}

function stopDrag() {
  isDraggingPhoto = false;
  isDraggingLogo = false;
  canvas.classList.remove('is-dragging');
  canvas.style.cursor = 'default';
}

// Mouse events
canvas.addEventListener('mousedown', (e) => {
  startDrag(e.clientX, e.clientY);
});

window.addEventListener('mousemove', (e) => {
  moveDrag(e.clientX, e.clientY);
});

window.addEventListener('mouseup', stopDrag);

// Touch events for mobile
canvas.addEventListener('touchstart', (e) => {
  if (e.touches.length === 1) {
    startDrag(e.touches[0].clientX, e.touches[0].clientY);
  }
}, { passive: true });

canvas.addEventListener('touchmove', (e) => {
  if ((!isDraggingPhoto && !isDraggingLogo) || e.touches.length !== 1) return;
  e.preventDefault();
  moveDrag(e.touches[0].clientX, e.touches[0].clientY);
}, { passive: false });

canvas.addEventListener('touchend', stopDrag);
canvas.addEventListener('touchcancel', stopDrag);

function handleImageUpload(e) {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(event) {
    const img = new Image();
    img.onload = function() {
      userImage = img;
      imgZoom = 1;
      imgPosX = 0;
      imgPosY = 0;
      zoomRange.value = 1;
      posYRange.value = 0;
      if (posXRange) posXRange.value = 0;
      removePhotoBtn.classList.remove('hidden');
      photoControls.classList.remove('hidden');
      canvas.classList.add('can-drag');
      renderCard();
    };
    img.src = event.target.result;
  };
  reader.readAsDataURL(file);
}

