// 1. Direct HD Download (Synchronous DataURL with Blob fallback)
downloadBtn.addEventListener('click', () => {
  const origHtml = downloadBtn.innerHTML;
  downloadBtn.innerHTML = '<span>⏳</span><span>കാർഡ് സേവ് ആകുന്നു... (Downloading)</span>';
  downloadBtn.style.opacity = '0.8';

  const prefix = appMode === 'obituary' ? 'KozhikodeVision_Obituary' : 'KozhikodeVision_NewsCard';
  const filename = `${prefix}_${Date.now()}.jpg`;

  function triggerDownload(href) {
    const a = document.createElement('a');
    a.download = filename;
    a.href = href;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      downloadBtn.innerHTML = '<span>✅</span><span>ഡൗൺലോഡ് പൂർത്തിയായി! (Saved)</span>';
      setTimeout(() => {
        downloadBtn.innerHTML = origHtml;
        downloadBtn.style.opacity = '1';
      }, 1500);
    }, 500);
  }

  // Synchronous DataURL download: 100% reliable on desktop and mobile browsers
  try {
    const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
    triggerDownload(dataUrl);
    return;
  } catch (err) {
    console.warn('toDataURL failed, attempting toBlob:', err);
  }

  // Fallback: toBlob
  try {
    canvas.toBlob((blob) => {
      if (!blob) {
        downloadBtn.innerHTML = origHtml;
        downloadBtn.style.opacity = '1';
        alert('ഡൗൺലോഡ് സാധ്യമായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.');
        return;
      }
      const url = URL.createObjectURL(blob);
      triggerDownload(url);
      setTimeout(() => URL.revokeObjectURL(url), 2000);
    }, 'image/jpeg', 0.95);
  } catch (e2) {
    downloadBtn.innerHTML = origHtml;
    downloadBtn.style.opacity = '1';
    alert('ഡൗൺലോഡ് പിശക്: ' + e2.message);
  }
});

// 2. Direct WhatsApp Share
whatsappBtn.addEventListener('click', async () => {
  const caption = getShareText();

  canvas.toBlob(async (blob) => {
    if (!blob) return;
    const file = new File([blob], 'Kozhikode_Vision_News.jpg', { type: 'image/jpeg' });

    // Web Share API (Direct mobile file share to WhatsApp)
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({
          files: [file],
          title: 'Kozhikode Vision News',
          text: caption
        });
        return;
      } catch (err) {
        if (err.name === 'AbortError') return;
      }
    }

    // Fallback: Download image and open WhatsApp with text
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.download = 'Kozhikode_Vision_News.jpg';
    a.href = url;
    a.click();

    setTimeout(() => {
      const waUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(caption)}`;
      window.open(waUrl, '_blank');
    }, 500);
  }, 'image/jpeg', 0.95);
});

// 3. Direct Facebook Share
facebookBtn.addEventListener('click', () => {
  const caption = getShareText();

  canvas.toBlob((blob) => {
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.download = 'Kozhikode_Vision_News.jpg';
    a.href = url;
    a.click();

    setTimeout(() => {
      // Open Facebook Sharer / Creator studio
      const fbUrl = `https://www.facebook.com/sharer/sharer.php?quote=${encodeURIComponent(caption)}`;
      window.open(fbUrl, '_blank');
    }, 500);
  }, 'image/jpeg', 0.95);
});

